Your expense tracker is below. Add an item with its amount, category and date, set a monthly budget, and it shows your total, what is left and a split by category. Pick a month to look at earlier ones. It keeps your entries on this device when the chat allows it, and otherwise only while the page is open.

```page
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:14px;background:#fafaf7;color:#222;font-size:14px}
  h2{margin:0 0 10px;font-size:18px}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}
  input,select,button{font:inherit;padding:7px 9px;border:1px solid #ccc;border-radius:6px;background:#fff}
  button{background:#2f7d5b;color:#fff;border-color:#2f7d5b;cursor:pointer}
  button.x{background:#fff;color:#a33;border-color:#ddd;padding:3px 8px}
  .cards{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}
  .card{flex:1;min-width:110px;background:#fff;border:1px solid #e3e3dc;border-radius:8px;padding:10px}
  .card b{display:block;font-size:18px;margin-top:3px}
  .bar{height:8px;background:#e8efe9;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar i{display:block;height:100%;background:#2f7d5b}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #e3e3dc;border-radius:8px}
  td,th{padding:7px 8px;border-bottom:1px solid #eee;text-align:left}
  td.n,th.n{text-align:right}
  .over{color:#b33}
  .muted{color:#777}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="row">
  <label>Month <input type="month" id="month"></label>
  <label>Budget (₹) <input type="number" id="budget" min="0" style="width:110px"></label>
</div>

<div class="row">
  <input id="name" placeholder="What for?" style="flex:2;min-width:120px">
  <input id="amt" type="number" min="0" placeholder="Amount (₹)" style="width:110px">
  <select id="cat">
    <option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option>
    <option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
  </select>
  <input type="date" id="date">
  <button id="add">Add</button>
</div>

<div class="cards">
  <div class="card">Spent<b id="spent">₹0</b></div>
  <div class="card">Left<b id="left">-</b></div>
  <div class="card">Entries<b id="count">0</b></div>
</div>

<div id="cats"></div>

<table>
  <thead><tr><th>Date</th><th>Item</th><th>Category</th><th class="n">Amount</th><th></th></tr></thead>
  <tbody id="rows"></tbody>
</table>
<p class="muted" id="empty">No expenses for this month yet.</p>

<script>
var S={budget:0,items:[]};
try{var d=localStorage.getItem('foo-expenses');if(d)S=JSON.parse(d);}catch(e){}
function save(){try{localStorage.setItem('foo-expenses',JSON.stringify(S));}catch(e){}}
function $(i){return document.getElementById(i);}
function inr(n){return '₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});}
var today=new Date().toISOString().slice(0,10);
$('date').value=today;
$('month').value=today.slice(0,7);
$('budget').value=S.budget||'';

function render(){
  var m=$('month').value;
  var list=S.items.filter(function(x){return x.date.slice(0,7)===m;})
    .sort(function(a,b){return a.date<b.date?1:-1;});
  var total=0,by={};
  list.forEach(function(x){total+=x.amt;by[x.cat]=(by[x.cat]||0)+x.amt;});
  $('spent').textContent=inr(total);
  $('count').textContent=list.length;
  var l=$('left');
  if(S.budget>0){
    var r=S.budget-total;
    l.textContent=r<0?'-'+inr(-r):inr(r);
    l.className=r<0?'over':'';
  }else{l.textContent='-';l.className='';}
  var c=$('cats');c.innerHTML='';
  Object.keys(by).sort(function(a,b){return by[b]-by[a];}).forEach(function(k){
    var w=document.createElement('div');
    var t=document.createElement('div');
    t.textContent=k+': '+inr(by[k]);
    var b=document.createElement('div');b.className='bar';
    var i=document.createElement('i');i.style.width=Math.round(by[k]/total*100)+'%';
    b.appendChild(i);w.appendChild(t);w.appendChild(b);c.appendChild(w);
  });
  var tb=$('rows');tb.innerHTML='';
  list.forEach(function(x){
    var tr=document.createElement('tr');
    [x.date,x.name,x.cat].forEach(function(v){
      var td=document.createElement('td');td.textContent=v;tr.appendChild(td);
    });
    var a=document.createElement('td');a.className='n';a.textContent=inr(x.amt);tr.appendChild(a);
    var d=document.createElement('td');
    var bt=document.createElement('button');bt.className='x';bt.textContent='✕';
    bt.onclick=function(){S.items=S.items.filter(function(y){return y!==x;});save();render();};
    d.appendChild(bt);tr.appendChild(d);tb.appendChild(tr);
  });
  $('empty').style.display=list.length?'none':'block';
}

$('add').onclick=function(){
  var a=parseFloat($('amt').value);
  if(!(a>0)||!$('date').value)return;
  S.items.push({name:$('name').value.trim()||$('cat').value,amt:a,cat:$('cat').value,date:$('date').value});
  $('name').value='';$('amt').value='';
  save();render();
};
$('budget').oninput=function(){S.budget=parseFloat(this.value)||0;save();render();};
$('month').onchange=render;
render();
</script>
</body>
</html>
```
